INSERT INTO public.product_catalog_item_sources (tenant_id, item_id, source_type, source_ref, source_url, captured_at, reconciliation_status, payload)
SELECT t.id, i.id, s.source_type, s.source_ref, s.source_url, s.captured_at, s.reconciliation_status, s.payload
FROM _pc_sources s CROSS JOIN _pc_tenant t JOIN public.product_catalog_items i ON i.tenant_id = t.id AND i.item_code = s.item_code
ON CONFLICT (tenant_id, source_type, source_ref) DO UPDATE SET source_url = EXCLUDED.source_url,
  captured_at = EXCLUDED.captured_at, reconciliation_status = EXCLUDED.reconciliation_status, payload = EXCLUDED.payload
WHERE product_catalog_item_sources.item_id = EXCLUDED.item_id AND (product_catalog_item_sources.source_url IS DISTINCT FROM EXCLUDED.source_url
  OR product_catalog_item_sources.captured_at IS DISTINCT FROM EXCLUDED.captured_at
  OR product_catalog_item_sources.reconciliation_status IS DISTINCT FROM EXCLUDED.reconciliation_status
  OR product_catalog_item_sources.payload IS DISTINCT FROM EXCLUDED.payload);
DO $$ BEGIN IF EXISTS (SELECT 1 FROM _pc_sources s CROSS JOIN _pc_tenant t
  JOIN public.product_catalog_items i ON i.tenant_id = t.id AND i.item_code = s.item_code
  LEFT JOIN public.product_catalog_item_sources x ON x.tenant_id = t.id AND x.source_type = s.source_type AND x.source_ref = s.source_ref
  WHERE x.item_id IS DISTINCT FROM i.id) THEN RAISE EXCEPTION 'Origem já vinculada a outro item'; END IF; END $$;

