INSERT INTO public.product_catalog_assets (tenant_id, storage_path, public_url, sha256, mime_type, file_size_bytes, source_ref)
SELECT t.id, a.storage_path, 'https://gfwwawazivmuqyctjsxj.supabase.co/storage/v1/object/public/product-catalog/'::text || a.storage_path, a.sha256, a.mime_type, a.file_size_bytes, a.source_ref
FROM _pc_assets a CROSS JOIN _pc_tenant t ON CONFLICT (tenant_id, sha256) DO NOTHING;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM _pc_assets a CROSS JOIN _pc_tenant t
  LEFT JOIN public.product_catalog_assets x ON x.tenant_id = t.id AND x.sha256 = a.sha256
  WHERE x.id IS NULL OR x.storage_path <> a.storage_path OR x.mime_type <> a.mime_type OR x.file_size_bytes <> a.file_size_bytes)
  THEN RAISE EXCEPTION 'Arquivo de imagem divergente do registrado'; END IF; END $$;

