INSERT INTO public.product_catalog_item_images (tenant_id, item_id, asset_id, display_order, is_primary, review_status, shared_note)
SELECT t.id, i.id, a.id, v.display_order, v.is_primary, v.review_status, v.shared_note
FROM _pc_links v CROSS JOIN _pc_tenant t
JOIN public.product_catalog_items i ON i.tenant_id = t.id AND i.item_code = v.item_code
JOIN public.product_catalog_assets a ON a.tenant_id = t.id AND a.sha256 = v.asset_sha256
ON CONFLICT (tenant_id, item_id, asset_id) DO NOTHING;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM _pc_links v CROSS JOIN _pc_tenant t
  JOIN public.product_catalog_items i ON i.tenant_id = t.id AND i.item_code = v.item_code
  JOIN public.product_catalog_assets a ON a.tenant_id = t.id AND a.sha256 = v.asset_sha256
  LEFT JOIN public.product_catalog_item_images l ON l.tenant_id = t.id AND l.item_id = i.id AND l.asset_id = a.id
  WHERE l.item_id IS NULL) THEN RAISE EXCEPTION 'Vínculo de imagem ausente após a carga'; END IF; END $$;

COMMIT;
